import type { Candle, Instrument, InstrumentKind, OrderBook, Tick, Timeframe, VenueId } from '@kinetix/shared';

import { buildBook, bookSeedFor } from './orderBook.ts';
import { createRng, hashSeed, type Rng } from './rng.ts';

/* ============================================================================
 * The market simulator.
 *
 * History is generated by a regime-switching geometric process: the tape moves
 * between trend, mean-reversion and volatility-expansion states, so a backtest
 * encounters genuinely different market conditions instead of one long drift.
 * Everything is seeded, so a given seed reproduces the same history exactly.
 * ==========================================================================*/

export const TIMEFRAME_MS: Record<Timeframe, number> = {
  '1m': 60_000,
  '15m': 900_000,
  '1h': 3_600_000,
  '1d': 86_400_000,
};

const MS_PER_YEAR = 365 * 24 * 60 * 60 * 1000;
const barsPerYear = (timeframe: Timeframe): number => MS_PER_YEAR / TIMEFRAME_MS[timeframe];

/** How much history to materialise per timeframe when a series is first touched. */
const SERIES_LENGTH: Record<Timeframe, number> = {
  '1m': 2_880, // 2 days
  '15m': 3_456, // 36 days
  '1h': 2_400, // 100 days
  '1d': 1_095, // 3 years, matching the mockups' "1,095 Daily Candles"
};

interface RegimeProfile {
  drift: number;
  volMultiplier: number;
}

const REGIMES = ['trend_up', 'trend_down', 'mean_revert', 'vol_expansion'] as const;
type Regime = (typeof REGIMES)[number];

const REGIME_PROFILES: Record<Regime, RegimeProfile> = {
  trend_up: { drift: 1, volMultiplier: 0.85 },
  trend_down: { drift: -1, volMultiplier: 0.95 },
  mean_revert: { drift: -0.15, volMultiplier: 0.7 },
  vol_expansion: { drift: 0.1, volMultiplier: 2.15 },
};

const REGIME_TRANSITIONS: Record<Regime, readonly [Regime, number][]> = {
  trend_up: [
    ['trend_up', 0.9],
    ['mean_revert', 0.08],
    ['trend_down', 0.02],
  ],
  trend_down: [
    ['trend_down', 0.88],
    ['mean_revert', 0.09],
    ['trend_up', 0.03],
  ],
  mean_revert: [
    ['mean_revert', 0.86],
    ['trend_up', 0.08],
    ['trend_down', 0.04],
    ['vol_expansion', 0.02],
  ],
  vol_expansion: [
    ['vol_expansion', 0.7],
    ['mean_revert', 0.2],
    ['trend_up', 0.06],
    ['trend_down', 0.04],
  ],
};

export interface InstrumentSpec {
  symbol: string;
  displayName: string;
  venue: VenueId;
  venueLabel: string;
  kind: InstrumentKind;
  base: string;
  quote: string;
  tickSize: number;
  priceDecimals: number;
  /** Seed price the simulated series starts from. */
  basePrice: number;
  /** Annualised volatility, e.g. 0.62 for BTC. */
  annualVol: number;
  /** Structural drift, expressed as a fraction of volatility per step. */
  driftBias: number;
  /** Order-book size scale at the touch. */
  sizeScale: number;
  /** Per-bar traded volume scale. */
  volumeScale: number;
  priceTarget: number;
  kotak?: { tradingSymbol: string; exchangeSegment: string };
}

