export function instrumentSpec(symbol: string): InstrumentSpec {
  const spec = INSTRUMENTS.find((candidate) => candidate.symbol === symbol);
  if (!spec) throw new Error(`Unknown instrument: ${symbol}`);
  return spec;
}

export function toInstrument(spec: InstrumentSpec): Instrument {
  return {
    symbol: spec.symbol,
    displayName: spec.displayName,
    venue: spec.venue,
    venueLabel: spec.venueLabel,
    kind: spec.kind,
    base: spec.base,
    quote: spec.quote,
    tickSize: spec.tickSize,
    priceDecimals: spec.priceDecimals,
    ...(spec.kotak ? { exchangeSegment: spec.kotak.exchangeSegment, tradingSymbol: spec.kotak.tradingSymbol } : {}),
  };
}

export interface GenerateCandlesOptions {
  symbol: string;
  timeframe: Timeframe;
  count: number;
  /** Open time of the final candle. The series runs backwards from here. */
  endTs: number;
  seed: number;
  /**
   * Close of the final candle. The generated walk is rescaled so the series
   * *finishes* on this price, which is what keeps history continuous with the
   * live tape: the last historical bar and the next tick are the same number by
   * construction rather than by coincidence.
   */
  endPrice?: number;
}

function pickRegime(rng: Rng, current: Regime): Regime {
  const roll = rng.next();
  let cumulative = 0;
  for (const [regime, weight] of REGIME_TRANSITIONS[current]) {
    cumulative += weight;
    if (roll <= cumulative) return regime;
  }
  return current;
}

/**
 * Pure, reproducible candle generation. Same inputs always produce the same
 * series — the property the backtest tests assert on.
 *
 * The walk runs in dimensionless units starting at 1 and is rescaled at the end
 * so the series closes on `endPrice`. Two consequences matter:
 *
 *  - A series can never end somewhere unrelated to the live tape, which is what
 *    previously produced a chart whose final candle jumped ~300% away from the
 *    price line drawn beside it.
 *  - Drift is an *annual* rate divided by the bars in a year. Expressing it as a
 *    multiple of per-bar volatility instead compounded over thousands of bars,
 *    so the three-year daily series covered an 18x range.
 */
export function generateCandles(options: GenerateCandlesOptions): Candle[] {
  const spec = instrumentSpec(options.symbol);
  const stepMs = TIMEFRAME_MS[options.timeframe];
  const rng = createRng(hashSeed(`${options.seed}:${options.symbol}:${options.timeframe}`));
  const periodsPerYear = barsPerYear(options.timeframe);
  const stepVol = spec.annualVol / Math.sqrt(periodsPerYear);

  let price = 1;
  let regime: Regime = 'trend_up';
  const walk: Array<{ o: number; h: number; l: number; c: number; v: number }> = [];

  for (let i = 0; i < options.count; i += 1) {
    if (i % 48 === 0) regime = pickRegime(rng, regime);

    const profile = REGIME_PROFILES[regime];
    const open = price;
    const shock = rng.boundedNormal(1);
    const drift = (profile.drift * spec.driftBias) / periodsPerYear;
    const close = Math.max(1e-6, open * Math.exp(drift + stepVol * profile.volMultiplier * shock));
    const wick = Math.abs(close - open) + open * stepVol * profile.volMultiplier * rng.range(0.15, 0.75);
    const high = Math.max(open, close) + wick * rng.range(0.2, 0.8);
    const low = Math.max(1e-6, Math.min(open, close) - wick * rng.range(0.2, 0.8));

    const moveRatio = Math.abs(close - open) / open;
    const volume = spec.volumeScale * (1 + moveRatio * 42) * rng.range(0.55, 1.85);

    walk.push({ o: open, h: high, l: low, c: close, v: Math.round(volume) });
    price = close;
  }

  const endPrice = options.endPrice ?? spec.basePrice;
  const scale = endPrice / (walk[walk.length - 1]?.c ?? 1);

  return walk.map((bar, index) => {
    const o = round(bar.o * scale, spec.priceDecimals);
    const c = round(bar.c * scale, spec.priceDecimals);
    const h = round(bar.h * scale, spec.priceDecimals);
    const l = round(bar.l * scale, spec.priceDecimals);
    return {
      t: options.endTs - (options.count - 1 - index) * stepMs,
      o,
      c,
      // Rounding each price independently can push a wick inside its own body by
      // one tick, so the body is re-imposed on the range.
      h: Math.max(h, o, c),
      l: Math.min(l, o, c),
      v: bar.v,
    };
  });
}

function round(value: number, decimals: number): number {
  const factor = 10 ** decimals;
  return Math.round(value * factor) / factor;
}

export interface MarketSnapshot {
  symbol: string;
  price: number;
  change24hUsd: number;
  change24hPct: number;
  high24h: number;
  low24h: number;
  volume24h: number;
  /** Share of ticks that passed the plausibility filter, as a percentage. */
  tickQualityPct: number;
  regime: Regime;
}

export interface MarketSimulator {
  specs(): readonly InstrumentSpec[];
  spec(symbol: string): InstrumentSpec;
  instruments(): Instrument[];
  /** Cached series, extended and rolled forward by `advance()`. */
  candles(symbol: string, timeframe: Timeframe, count?: number): Candle[];
  snapshot(symbol: string): MarketSnapshot;
  book(symbol: string, depth?: number): OrderBook;
  /** Advance one tick; returns the ticks and books produced. */
  advance(): { ticks: Tick[]; books: OrderBook[]; at: number };
  /** Price of the most recent close. */
  price(symbol: string): number;
  regime(symbol: string): Regime;
}

interface SymbolState {
  price: number;
  regime: Regime;
  series: Map<Timeframe, Candle[]>;
  ticksTotal: number;
  ticksAccepted: number;
  rng: Rng;
  step: number;
}

export interface MarketSimulatorOptions {
  /** Ticks per second the engine drives `advance()` at, used to annualise drift. */
  tickHz?: number;
}

export function createMarketSimulator(
  seed: number,
  now: () => number = Date.now,
  options: MarketSimulatorOptions = {},
): MarketSimulator {
  const states = new Map<string, SymbolState>();
  const ticksPerYear = Math.max(1, options.tickHz ?? 4) * 60 * 60 * 24 * 365;

  const stateFor = (symbol: string): SymbolState => {
    const existing = states.get(symbol);
    if (existing) return existing;
    const spec = instrumentSpec(symbol);
    const created: SymbolState = {
      price: spec.basePrice,
      regime: 'trend_up',
      series: new Map(),
      ticksTotal: 0,
      ticksAccepted: 0,
      rng: createRng(hashSeed(`${seed}:live:${symbol}`)),
      step: 0,
    };
    states.set(symbol, created);
    return created;
  };

  const ensureSeries = (symbol: string, timeframe: Timeframe, minCount: number): Candle[] => {
    const state = stateFor(symbol);
    const needed = Math.max(minCount, SERIES_LENGTH[timeframe]);
    const existing = state.series.get(timeframe);
    if (existing && existing.length >= needed) return existing;

    // Materialise the series anchored on the current live price, so the newest
    // historical bar and the next tick are the same price. Asking for deeper
    // history re-materialises the series (the tail is unchanged; the walk behind
    // it is new), which is why the count is part of the cache key above.
    const stepMs = TIMEFRAME_MS[timeframe];
    const endTs = Math.floor(now() / stepMs) * stepMs;
    const series = generateCandles({ symbol, timeframe, count: needed, endTs, seed, endPrice: state.price });
    state.series.set(timeframe, series);
    return series;
  };

  const price = (symbol: string): number => stateFor(symbol).price;

  const simulator: MarketSimulator = {
    specs: () => INSTRUMENTS,
    spec: instrumentSpec,
    instruments: () => INSTRUMENTS.map(toInstrument),

    candles: (symbol, timeframe, count) => {
      const series = ensureSeries(symbol, timeframe, count ?? SERIES_LENGTH[timeframe]);
      return count === undefined ? series : series.slice(-count);
    },

    price,

    regime: (symbol) => stateFor(symbol).regime,

    snapshot: (symbol) => {
      const spec = instrumentSpec(symbol);
      const state = stateFor(symbol);
      const daily = simulator.candles(symbol, '1d', 2);
      const previousClose = daily[0]?.c ?? spec.basePrice;
      const change = state.price - previousClose;
      const window = simulator.candles(symbol, '1m', 1_440);
      const high = window.reduce((acc, candle) => Math.max(acc, candle.h), state.price);
      const low = window.reduce((acc, candle) => Math.min(acc, candle.l), state.price);
      const volume = window.reduce((acc, candle) => acc + candle.v, 0);
      const quality = state.ticksTotal === 0 ? 99.8 : (state.ticksAccepted / state.ticksTotal) * 100;

      return {
        symbol,
        price: state.price,
        change24hUsd: round(change, spec.priceDecimals),
        change24hPct: Number(((change / previousClose) * 100).toFixed(2)),
        high24h: round(high, spec.priceDecimals),
        low24h: round(low, spec.priceDecimals),
        volume24h: Math.round(volume),
        tickQualityPct: Number(quality.toFixed(2)),
        regime: state.regime,
      };
    },

    book: (symbol, depth = 1) => {
      const spec = instrumentSpec(symbol);
      const state = stateFor(symbol);
      const raw = buildBook({
        mid: state.price,
        tickSize: spec.tickSize,
        depth,
        seed: bookSeedFor(symbol, spec.basePrice),
        step: state.step,
        sizeScale: spec.sizeScale,
      });
      return {
        symbol,
        bids: raw.bids,
        asks: raw.asks,
        spread: raw.spread,
        spreadPct: raw.spreadPct,
        mid: raw.mid,
        ts: now(),
      };
    },

    advance: () => {
      const at = now();
      const ticks: Tick[] = [];
      const books: OrderBook[] = [];

      for (const spec of INSTRUMENTS) {
        const state = stateFor(spec.symbol);
        state.step += 1;
        // Resample the regime on a slow cadence so a live session actually
        // experiences multiple market conditions.
        if (state.step % 400 === 0) state.regime = pickRegime(state.rng, state.regime);

        const profile = REGIME_PROFILES[state.regime];
        const tickVol = (spec.annualVol / Math.sqrt(ticksPerYear)) * profile.volMultiplier;
        // Annual drift spread across a year of ticks. Scaling it with per-tick
        // volatility instead compounded to roughly 240% of drift per day.
        const drift = (profile.drift * spec.driftBias) / ticksPerYear;
        const shock = state.rng.boundedNormal(1);
        const previous = state.price;
        const next = Math.max(spec.tickSize * 2, previous * Math.exp(drift + tickVol * shock));

        const clipped = Math.abs(next / previous - 1) > tickVol * 3.2;
        state.ticksTotal += 1;
        if (!clipped) state.ticksAccepted += 1;
        state.price = round(clipped ? previous * (1 + tickVol * Math.sign(shock) * 0.5) : next, spec.priceDecimals);

        const stepMs = TIMEFRAME_MS['1m'];
        const bucket = Math.floor(at / stepMs) * stepMs;
        const tickVolume = Math.max(1, Math.round(spec.volumeScale * state.rng.range(0.02, 0.12)));

        for (const timeframe of Object.keys(TIMEFRAME_MS) as Timeframe[]) {
          const series = state.series.get(timeframe);
          if (!series || series.length === 0) continue;
          const bucketMs = Math.floor(at / TIMEFRAME_MS[timeframe]) * TIMEFRAME_MS[timeframe];
          const last = series[series.length - 1];
          if (!last) continue;
          if (last.t === bucketMs) {
            last.c = state.price;
            last.h = Math.max(last.h, state.price);
            last.l = Math.min(last.l, state.price);
            last.v += tickVolume;
          } else if (bucketMs > last.t) {
            series.push({ t: bucketMs, o: last.c, h: Math.max(last.c, state.price), l: Math.min(last.c, state.price), c: state.price, v: tickVolume });
          }
        }

        ticks.push({ symbol: spec.symbol, price: state.price, t: bucket, v: tickVolume, ts: at });
        books.push(simulator.book(spec.symbol, 1));
      }

      return { ticks, books, at };
    },
  };

  return simulator;
}
